INSERT INTO beer_test_results (beer, producer, style, source, test_type, test_result, testing_source, testing_notes, test_date) VALUES
('Asahi Super Dry', 'Asahi Beer Ltd.', 'Pale Lager', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2015/03/asahi-super-dry.html', 'Very dark color for a lager, bland taste. Consumer reported no symptoms after drinking entire 12 oz bottle in 30 minutes (gluten intolerant, not celiac).', '2015-03-01'),
('Beck''s', 'Anheuser-Busch InBev', 'Pilsner', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/06/becks-us-brewed.html', 'US-brewed version from St. Louis. Visually inconclusive test result. Some alternative testing showed less than 5ppm. Consumer reported no reaction after drinking in 30 minutes. Noted quality decline since 2012 shift to US brewing.', '2014-06-01'),
('Brooklyn Lager', 'Brooklyn Brewery', 'American Amber Lager', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2015/10/brooklyn-lager.html', 'Despite rumors of being low gluten, tested over 20ppm threshold. Consumer drank entire 12 oz bottle in 30 minutes with no symptoms. Described as excessively malty with citrus notes.', '2015-10-01'),
('Bud Light', 'Anheuser-Busch InBev', 'Pale Lager', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/04/bud-light.html', 'Tested positive at both 10ppm and 20ppm levels. Consumer expressed surprise given its status as America''s best-selling beer. No reaction reported after consumption.', '2014-04-01'),
('Carlsberg', 'Carlsberg Group', 'Pale Lager', 'Bottle', 'E-Z Gluten', 'Negative at 20ppm', 'http://gluteninbeer.blogspot.com/2014/08/carlsberg.html', 'Brewed in Denmark. Qualifies as gluten-free under FDA standards. Consumer drank 330ml bottle in 30 minutes with no symptoms. Described as unremarkable industrial Euro-lager with sour metallic aftertaste.', '2014-08-01'),
('Chimay Premiere', 'Scourmont Abbey', 'Abbey Dubbel', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2015/04/chimay-premiere.html', 'Contains wheat flour/starch (10-15%) as ingredient. Consumer drank entire 750ml bottle in 2 hours with no effects, but commenter reported significant gluten reaction. Individual tolerance varies widely.', '2015-04-01'),
('Coors Light', 'Coors Brewing Company', 'Pale Lager', 'Can', 'E-Z Gluten', 'Negative at 10ppm', 'http://gluteninbeer.blogspot.com/2014/02/coors-light.html', 'Tests below 10ppm, well under FDA''s 20ppm threshold. Consumer drank entire 24 oz can over one hour without reaction.', '2014-02-01'),
('Corona Extra', 'Cerveceria Modelo', 'Pale Lager', 'Bottle', 'E-Z Gluten', 'Negative at 10ppm', 'http://gluteninbeer.blogspot.com/2014/01/corona-extra.html', 'Tests below 10ppm. Consumer safely consumed three 12 oz bottles over 3-4 hours without reaction.', '2014-01-01'),
('Duvel', 'Brouwerij Duvel Moortgat', 'Belgian Golden Ale', 'Bottle', 'E-Z Gluten', 'Negative at 20ppm', 'http://gluteninbeer.blogspot.com/2014/02/duvel.html', 'Tests below 20ppm. Consumer drank 11.2 oz bottle over one hour with no symptoms. 8.5% ABV. Described as delicate but sophisticated with citrus notes.', '2014-02-01'),
('Fat Tire', 'New Belgium Brewing', 'Amber Ale', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/03/fat-tire.html', 'Well over 20ppm. Consumer drank full 12 oz bottle with no typical gluten effects. Described as toasty with nutty finish and low carbonation.', '2014-03-01'),
('Foster''s Lager', 'Foster''s', 'Pale Lager', 'Can', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2015/01/fosters-lager.html', 'Brewed in Texas. More than 20ppm. Consumer drank 25.4 oz can over 60 minutes without noticeable effects.', '2015-01-01'),
('Guinness', 'Diageo', 'Irish Dry Stout', 'Draft', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/01/guinness.html', 'Well over 20ppm. Many readers report tolerance despite celiac diagnosis, with theories about roasting processes altering gluten proteins. Medical professionals caution lack of symptoms doesn''t guarantee absence of intestinal damage.', '2014-01-01'),
('Heineken', 'Heineken Brouwerijen', 'Pale Lager', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/01/heineken.html', 'Well over 20ppm. Consumer drank three 12 oz bottles over 3-4 hours without reaction.', '2014-01-01'),
('Heineken Light', 'Heineken Brouwerijen', 'Pale Lager', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/01/heineken-light.html', 'Well over 20ppm. Disappointing result as most domestic light beers test below 20ppm. Consumer drank three bottles over 3-4 hours without reaction.', '2014-01-01'),
('Hitachino Nest Red Rice Ale', 'Kiuchi', 'Belgian Strong Pale Ale', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2015/12/hitachino-nest-red-rice-ale.html', 'More than 20ppm. Inaccurately classified as gluten-free in some stores despite containing barley malts alongside red rice. Consumer drank 12 oz without symptoms.', '2015-12-01'),
('Kirin Light', 'Anheuser-Busch', 'Light Lager', 'Bottle', 'E-Z Gluten', 'Negative at 20ppm', 'http://gluteninbeer.blogspot.com/2015/07/kirin-light.html', 'Less than 20ppm. Consumer drank entire 22 oz bottle in 30 minutes with no effects. Unfavorable taste described as sweaty and flat.', '2015-07-01'),
('La Fin du Monde', 'Unibroue', 'Belgian-Style Tripel', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/11/la-fin-du-monde.html', 'More than 20ppm. Consumer drank entire 750ml bottle within 2 hours with no symptoms. Described as well-balanced with flowery aroma and Belgian yeast flavor, slightly over-carbonated.', '2014-11-01'),
('Leffe', 'Anheuser-Busch InBev', 'Blonde Belgian Abbey Ale', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/03/leffe.html', 'Over 20ppm. Consumer drank full bottle with no gluten effects. Praised Belgian character but fails FDA gluten-free standards.', '2014-03-01'),
('Maudite', 'Unibroue', 'Belgian Strong Dark Ale', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2015/12/maudite.html', 'More than 20ppm. Consumer drank entire 750ml bottle over 2 hours with no gluten effects.', '2015-12-01'),
('Miller High Life', 'Miller Brewing Company', 'American Pale Lager', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2015/06/miller-high-life.html', 'More than 20ppm. Consumer drank entire 24 oz bottle over 90 minutes while mowing lawn with no effects. Contains corn syrup.', '2015-06-01'),
('Miller Lite', 'Miller Brewing Company', 'Pale Lager', 'Can', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2015/02/miller-lite.html', 'More than 20ppm. Consumer drank 12 oz can in 30 minutes and felt rather bloated but no serious gluten effects.', '2015-02-01'),
('Modelo Especial', 'Cerveceria Modelo', 'Pale Lager', 'Can', 'E-Z Gluten', 'Negative at 20ppm', 'http://gluteninbeer.blogspot.com/2014/01/modelo-especial.html', 'Less than 20ppm. Consumer drank entire 24 oz can within one hour with no adverse reaction.', '2014-01-01'),
('Negra Modelo', 'Cerveceria Modelo', 'Vienna Lager', 'Bottle', 'E-Z Gluten', 'Negative at 20ppm', 'http://gluteninbeer.blogspot.com/2014/01/negra-modelo.html', 'Less than 20ppm. Consumer drank 12 oz bottle with no gluten effects. Previously avoided dark beers based on assumptions about gluten content.', '2014-01-01'),
('Newcastle Brown Ale', 'Newcastle Brewery', 'English Brown Ale', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/01/newcastle-brown-ale.html', 'Well over 20ppm. Consumer drank entire 12 oz bottle over one hour without noticeable reaction.', '2014-01-01'),
('Omission Pale Ale', 'Widmer Brothers', 'American Pale Ale', 'Bottle', 'E-Z Gluten', 'Negative at 20ppm', 'http://gluteninbeer.blogspot.com/2014/10/omission-pale-ale.html', 'Less than 20ppm. Uses Brewers Clarex enzyme to break apart gluten proteins. Independent lab validation confirms lack of measurable gluten. Some celiacs report reactions despite low gluten result, suggesting other factors may affect individuals.', '2014-10-01'),
('Orval', 'Abbaye Notre-Dame d''Orval', 'Belgian Pale Ale', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2015/05/orval.html', 'More than 20ppm. Consumer drank entire 12 oz bottle in 45 minutes with no noticeable effects.', '2015-05-01'),
('Pabst Blue Ribbon', 'Pabst Brewing Company', 'Pale Lager', 'Can', 'E-Z Gluten', 'Negative at 20ppm', 'http://gluteninbeer.blogspot.com/2014/01/pabst-blue-ribbon.html', 'Less than 20ppm. Consumer drank entire 24 oz can in 45 minutes without reaction. However, commenter reported different batch (exp Mar 2015) tested Very High Positive at 10ppm, suggesting batch variability.', '2014-01-01'),
('Peroni Nastro Azzurro', 'Peroni', 'Pale Lager', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/07/peroni-nastro-azzurro.html', 'More than 20ppm. Consumer drank entire bottle within 30 minutes with no noticeable reactions.', '2014-07-01'),
('Pilsner Urquell', 'Pilsner Urquell Brewery', 'Pilsner', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/09/pilsner-urquell.html', 'More than 20ppm. Consumer drank entire bottle within 30 minutes with no adverse effects. Sweet and malty taste with bitter finish.', '2014-09-01'),
('Red Stripe', 'Desnoes & Geddes Limited', 'Pale Lager', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/04/red-stripe.html', 'More than 20ppm. US version brewed in Pennsylvania since 2012. Label changed from ''Imported Jamaican Lager'' to ''Jamaican Style Lager''. Consumer drank bottle in 30 minutes without symptoms. Commenter suggests later production may have returned to Jamaica using cassava.', '2014-04-01'),
('Sapporo', 'Sapporo Breweries', 'Pale Lager', 'Can', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/02/sapporo.html', 'Well over 20ppm. Brewed in Canada. Brewer states not gluten-free. Consumer felt slightly bloated after 22 oz can over one hour. Commenters suggest high-temperature brewing may reduce bioavailable gluten.', '2014-02-01'),
('Sierra Nevada Pale Ale', 'Sierra Nevada Brewing Co', 'American Pale Ale', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/03/sierra-nevada-pale-ale.html', 'Well over 20ppm. Consumer drank bottle without adverse effects despite high gluten content.', '2014-03-01'),
('Stella Artois', 'AB InBev', 'Pale Lager', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/04/stella-artois.html', 'More than 20ppm. Consumer drank bottle in 30 minutes with no effects. Readers report varying experiences.', '2014-04-01'),
('Stone IPA', 'Stone Brewing', 'American IPA', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/01/stone-ipa.html', 'Well over 20ppm despite some accounts suggesting low gluten. Consumer drank two 12 oz bottles over three hours without reaction. Stone later introduced ''Stripped Away IPA'' as low-gluten alternative (less than 5ppm).', '2014-01-01'),
('Tecate', 'Cerveceria Modelo', 'Pale Lager', 'Can', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2014/11/tecate.html', 'More than 20ppm. Disappointing as previous Mexican beers tested under 20ppm. Consumer drank can in 45 minutes with no effects. Described as watery and forgettable.', '2014-11-01'),
('Tsingtao', 'Tsingtao Brewery Company', 'Pale Lager', 'Bottle', 'E-Z Gluten', 'Negative at 20ppm', 'http://gluteninbeer.blogspot.com/2014/03/tsingtao.html', 'Less than 20ppm. Consumer drank entire 12 oz bottle in 30 minutes with no gluten-related effects. Meets FDA gluten-free standards.', '2014-03-01'),
('Yanjing', 'Yanjing', 'Pale Lager', 'Bottle', 'E-Z Gluten', 'Positive at 20ppm', 'http://gluteninbeer.blogspot.com/2015/10/yanjing.html', 'Well over 20ppm. Does not meet FDA gluten-free standards. Consumer drank full 12 oz bottle without symptoms despite being gluten intolerant.', '2015-10-01');
